<script setup>
import { Link,useForm } from '@inertiajs/vue3';
const props=defineProps({branch:Object,ingredients:Object,movements:Object});
const forms={};
for(const row of props.ingredients.data) forms[row.id]=useForm({quantity_delta:'',reason:''});
const qty=(v)=>Number(v||0).toLocaleString('ar-EG',{maximumFractionDigits:3});
const labels={opening:'افتتاحي',adjustment:'تسوية',purchase_receipt:'استلام',consumption:'استهلاك',count_adjustment:'جرد',reversal:'عكس'};
function adjust(id){forms[id].post(`/admin/branches/${props.branch.id}/inventory/stock/${id}/adjustments`,{preserveScroll:true,onSuccess:()=>forms[id].reset()});}
</script>
<template><main dir="rtl" class="mx-auto max-w-7xl space-y-6 p-4 sm:p-6"><header><Link :href="`/admin/branches/${branch.id}/inventory`" class="text-sm font-bold text-amber-700">المخزون</Link><h1 class="mt-1 text-3xl font-black">الأرصدة والحركات</h1><p class="mt-1 text-sm text-slate-500">التسويات اليدوية تتطلب سببًا وتسجل في دفتر الحركات.</p></header><section class="overflow-hidden rounded-2xl border bg-white"><div class="border-b p-4 font-black">رصيد المكونات</div><div class="overflow-x-auto"><table class="w-full min-w-[900px] text-right text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="p-3">المكون</th><th class="p-3">المتاح</th><th class="p-3">المحجوز</th><th class="p-3">تسوية الرصيد</th></tr></thead><tbody class="divide-y"><tr v-for="i in ingredients.data" :key="i.id"><td class="p-3 font-bold">{{i.name}} <small class="text-slate-500">({{i.base_unit?.symbol}})</small></td><td class="p-3">{{qty((Number(i.stocks?.[0]?.on_hand_qty||0)-Number(i.stocks?.[0]?.reserved_qty||0)))}}</td><td class="p-3">{{qty(i.stocks?.[0]?.reserved_qty)}}</td><td class="p-3"><form @submit.prevent="adjust(i.id)" class="flex min-w-[390px] gap-2"><input v-model="forms[i.id].quantity_delta" type="number" step="0.001" required placeholder="+/- كمية" class="w-28 rounded-lg border-slate-300 text-sm"/><input v-model="forms[i.id].reason" required minlength="3" placeholder="سبب التسوية" class="flex-1 rounded-lg border-slate-300 text-sm"/><button class="rounded-lg bg-slate-900 px-3 py-2 text-xs font-bold text-white">حفظ</button></form></td></tr></tbody></table></div></section><section class="overflow-hidden rounded-2xl border bg-white"><div class="border-b p-4 font-black">دفتر الحركات</div><div class="overflow-x-auto"><table class="w-full min-w-[650px] text-right text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="p-3">التاريخ</th><th class="p-3">المكون</th><th class="p-3">النوع</th><th class="p-3">الكمية</th><th class="p-3">المرجع</th></tr></thead><tbody class="divide-y"><tr v-for="m in movements.data" :key="m.id"><td class="p-3">{{new Date(m.occurred_at).toLocaleString('ar-EG')}}</td><td class="p-3 font-bold">{{m.ingredient?.name}}</td><td class="p-3">{{labels[m.movement_type]||m.movement_type}}</td><td class="p-3" dir="ltr">{{qty(m.quantity_delta)}}</td><td class="p-3">{{m.reference||'—'}}</td></tr></tbody></table></div></section></main></template>
